SELECT * FROM loan_application


        AND status = #{status}


        AND guarantee_type = #{guaranteeType}


        AND loan_amount >= #{minAmount}


        AND loan_amount <= #{maxAmount}


        AND (customer_name LIKE CONCAT('%', #{keyword}, '%')
        OR customer_phone LIKE CONCAT('%', #{keyword}, '%'))


        AND DATE(created_at) >= #{startDate}


        AND DATE(created_at) <= #{endDate}


ORDER BY created_at DESC

